`timescale 1ns/1ps
module tb_tessera_vec_tile;
logic clk=0,rst_n=0,cmd_valid=0,cmd_ready,done_valid,done_ready=0,busy; logic [1:0] cmd_client=0,done_client; logic [2:0] cmd_op=0; logic [7:0] cmd_tag=0,done_tag; logic [15:0] operand_a=0,operand_b=0,done_result; logic [1:0] done_status; always #5 clk=~clk; tessera_vec_tile dut(.*); task tick; begin @(posedge clk); #1; end endtask
 task issue(input [2:0] op,input [15:0] a,b,input [7:0] tag); begin @(negedge clk); cmd_valid=1; cmd_op=op; operand_a=a; operand_b=b; cmd_tag=tag; cmd_client=2; #1; if(!cmd_ready) $fatal(1,"tile not ready"); tick(); cmd_valid=0; #1; if(!done_valid||done_tag!==tag||done_client!==2) $fatal(1,"completion metadata"); end endtask
 task check_result(input [15:0] value,input [1:0] status); begin if(done_result!==value||done_status!==status) $fatal(1,"result/status mismatch: got %h/%b expected %h/%b",done_result,done_status,value,status); done_ready=1; tick(); done_ready=0; end endtask
 initial begin repeat(2) tick(); rst_n=1; tick(); issue(0,12,30,8'h11); check_result(42,0); issue(1,7,9,8'h12); check_result(63,0); issue(2,-16'sd4,3,8'h13); check_result(-16'sd4,0); issue(3,-16'sd4,3,8'h14); check_result(3,0); issue(4,16'h55AA,16'h0FF0,8'h15); check_result(16'h5A5A,0); // Signed and truncation boundaries for the 16-bit ALU.
 issue(0,16'h7FFF,16'h0001,8'h17); check_result(16'h8000,0); issue(1,-16'sd32768,-16'sd1,8'h18); check_result(16'h8000,0); issue(1,-16'sd32768,-16'sd32768,8'h19); check_result(16'h0000,0); issue(2,16'h8000,16'h7FFF,8'h1A); check_result(16'h8000,0); issue(3,16'h8000,16'h7FFF,8'h1B); check_result(16'h7FFF,0); issue(7,1,2,8'h16); check_result(0,1); @(negedge clk); cmd_valid=1; cmd_op=0; operand_a=1; operand_b=2; cmd_tag=8'h22; done_ready=0; tick(); cmd_valid=0; #1; if(!done_valid||cmd_ready||done_tag!==8'h22||done_result!==3) $fatal(1,"completion backpressure failed"); done_ready=1; tick(); #1; if(done_valid) $fatal(1,"completion did not clear"); $display("PASS: vector ALU arithmetic, signed boundaries, truncation, opcode error, metadata, backpressure"); $finish; end
endmodule
